const fs = require("node:fs");
const path = require("node:path");

const moduleFiles = [
  "neighbor-expander.js",
  "graph-adapter.js",
  "search-expansion-controller.js",
  "session-controller.js",
  "plugin-entry.js",
];

function buildBundle() {
  const moduleEntries = moduleFiles.map((file) => {
    const source = fs.readFileSync(path.join(__dirname, file), "utf8");
    return `${JSON.stringify(file)}: function(module, exports, require) {\n${source}\n}`;
  });

  return `// Generated by build-main.js. Do not edit directly.
const __externalRequire = require;
const __modules = {
${moduleEntries.join(",\n")}
};
const __cache = {};

function __normalizeModuleId(id) {
  if (!id.startsWith("./")) return id;
  const relative = id.slice(2);
  return relative.endsWith(".js") ? relative : relative + ".js";
}

function __localRequire(id) {
  if (id === "obsidian") return __externalRequire(id);
  const moduleId = __normalizeModuleId(id);
  const factory = __modules[moduleId];
  if (!factory) throw new Error("Unknown bundled module: " + id);
  if (__cache[moduleId]) return __cache[moduleId].exports;

  const bundledModule = { exports: {} };
  __cache[moduleId] = bundledModule;
  factory(bundledModule, bundledModule.exports, __localRequire);
  return bundledModule.exports;
}

module.exports = __localRequire("./plugin-entry");
`;
}

const outputPath = path.join(__dirname, "main.js");
const bundle = buildBundle();
const current = fs.existsSync(outputPath)
  ? fs.readFileSync(outputPath, "utf8")
  : "";

if (current !== bundle) fs.writeFileSync(outputPath, bundle);

module.exports = { buildBundle, moduleFiles };
